/// 내부 헬퍼: 토큰 배열을 JSON 문자열로 반환
/// 형식: {"success":true,"tokens":["Let","Identifier(x)",...]}
///       {"success":false,"error":"..."}
pub fn get_tokens_json(code: &str) -> String {
    use fv_lang::lexer::Token;
    let lexer = match fv_lang::Lexer::new(code) {
        Ok(l) => l,
        Err(e) => return format!(r#"{{"success":false,"error":{}}}"#, json_str(&e.to_string())),
    };
