        Ok(t) => t,
        Err(e) => return format!(r#"{{"success":false,"error":{}}}"#, json_str(&e.to_string())),
    };

    let items: Vec<String> = tokens
        .iter()
        .map(|t| {
            let repr = match t {
                Token::Fn        => "Fn".into(),
                Token::Let       => "Let".into(),
                Token::If        => "If".into(),
