                Token::False     => "False".into(),
                Token::Plus      => "Plus".into(),
                Token::Minus     => "Minus".into(),
                Token::Star      => "Star".into(),
                Token::Slash     => "Slash".into(),
                Token::Percent   => "Percent".into(),
                Token::Assign    => "Assign".into(),
                Token::Eq        => "Eq".into(),
                Token::Ne        => "Ne".into(),
                Token::Lt        => "Lt".into(),
                Token::Le        => "Le".into(),
                Token::Gt        => "Gt".into(),
                Token::Ge        => "Ge".into(),
                Token::And       => "And".into(),
                Token::Or        => "Or".into(),
                Token::Not       => "Not".into(),
                Token::Arrow     => "Arrow".into(),
                Token::FatArrow  => "FatArrow".into(),
                Token::Pipe      => "Pipe".into(),
                Token::LParen    => "LParen".into(),
                Token::RParen    => "RParen".into(),
                Token::LBrace    => "LBrace".into(),
                Token::RBrace    => "RBrace".into(),
                Token::LBracket  => "LBracket".into(),
                Token::RBracket  => "RBracket".into(),
                Token::Comma     => "Comma".into(),
                Token::Dot       => "Dot".into(),
                Token::Colon     => "Colon".into(),
                Token::Semicolon => "Semicolon".into(),
                Token::Eof       => "Eof".into(),
                Token::Identifier(s) => format!("Identifier({})", s),
                Token::Integer(n)    => format!("Integer({})", n),
                Token::Float(f)      => format!("Float({})", f),
                Token::String(s)     => format!("String({})", s),
            };
            format!(r#""{}""#, repr)
        })
        .collect();

    format!(r#"{{"success":true,"tokens":[{}]}}"#, items.join(","))
}

/// 내부 헬퍼: 코드를 파싱해 AST JSON 반환 (파서 테스트용 공개 API)
/// 형식: {"success":true,"ast":"Program { definitions: [...], statements: [...] }"}
///       {"success":false,"error":"..."}
pub fn get_ast_json(code: &str) -> String {
    parse_ast(code)
}

// ── 내부 구현 ────────────────────────────────
fn run_fv(code: &str) -> String {
    let lexer = match fv_lang::Lexer::new(code) {
        Ok(l) => l,
        Err(e) => return format!(r#"{{"success":false,"error":"Lexer 오류: {}"}}"#, e),
    };
    let tokens = match lexer.tokenize() {
        Ok(t) => t,
        Err(e) => return format!(r#"{{"success":false,"error":"토큰 오류: {}"}}"#, e),
    };
    let parser = match fv_lang::Parser::new(tokens) {
        Ok(p) => p,
        Err(e) => return format!(r#"{{"success":false,"error":"파서 초기화 오류: {}"}}"#, e),
    };
    let ast = match parser.parse() {
        Ok(a) => a,
        Err(e) => return format!(r#"{{"success":false,"error":"파싱 오류: {}"}}"#, e),
    };
    match fv_lang::CodeGenerator::new().generate(&ast) {
        Ok(out) => format!(r#"{{"success":true,"output":{}}}"#, json_str(&out)),
        Err(e)  => format!(r#"{{"success":false,"error":"컴파일 오류: {}"}}"#, e),
    }
}

fn parse_ast(code: &str) -> String {
    let lexer = match fv_lang::Lexer::new(code) {
        Ok(l) => l,
        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
    };
    let tokens = match lexer.tokenize() {
        Ok(t) => t,
        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
    };
    let parser = match fv_lang::Parser::new(tokens) {
        Ok(p) => p,
        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
    };
    match parser.parse() {
        Ok(ast) => {
            let debug_str = format!("{:#?}", ast);
            format!(r#"{{"success":true,"ast":{}}}"#, json_str(&debug_str))
        }
        Err(e) => format!(r#"{{"success":false,"error":"{}"}}"#, e),
    }
}

fn json_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"'  => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x00'..='\x1f' => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

