/// Phase 4 — 코드 생성 단위 테스트
/// CodeGenerator: generate(), ast_to_ir(), IR 노드 구조 검증
#[cfg(test)]
mod tests {
    use fv_lang::{Lexer, Parser, CodeGenerator};
    use fv_lang::ir::IRNode;

    // ─── 헬퍼 ────────────────────────────────────────────────────────────────

    fn parse_program(code: &str) -> fv_lang::ast::Program {
        let lexer = Lexer::new(code).expect("Lexer 오류");
        let tokens = lexer.tokenize().expect("토큰화 오류");
        let parser = Parser::new(tokens).expect("파서 오류");
        parser.parse().expect("파싱 오류")
    }

    fn generate(code: &str) -> String {
        let program = parse_program(code);
        CodeGenerator::new()
            .generate(&program)
            .expect("코드 생성 오류")
    }

    fn to_ir(code: &str) -> fv_lang::ir::IRProgram {
        let program = parse_program(code);
        CodeGenerator::new()
            .ast_to_ir(&mut fv_lang::CodeGenerator::new(), &program)
    }

    // ast_to_ir 는 &mut self 가 필요 — 직접 사용
    macro_rules! ir {
        ($code:expr) => {{
            let program = parse_program($code);
            let mut cg = CodeGenerator::new();
            cg.ast_to_ir(&program).expect("IR 변환 오류")
        }};
    }

    // ─── 1. generate() 출력 포함 검증 ────────────────────────────────────────

    #[test]
    fn test_generate_contains_header_comment() {
        let out = generate("let x = 1;");
        assert!(out.contains("FV-Lang"), "헤더 없음: {}", out);
    }

    #[test]
    fn test_generate_fn_definition_in_output() {
        let code = "fn add(a, b) -> Int {\n  return a;\n}";
        let out = generate(code);
        assert!(out.contains("add"), "함수명 없음: {}", out);
    }

    #[test]
    fn test_generate_fn_empty_body() {
        let code = "fn noop() -> Int { return 0; }";
        let out = generate(code);
        assert!(out.contains("noop"), "함수명 없음: {}", out);
    }

    #[test]
    fn test_generate_two_functions() {
        let code = "fn f1() -> Int { return 1; }\nfn f2() -> Int { return 2; }";
        let out = generate(code);
        assert!(out.contains("f1"), "f1 없음: {}", out);
        assert!(out.contains("f2"), "f2 없음: {}", out);
    }

    #[test]
    fn test_generate_typedef_in_output() {
        let code = "type MyType;";
        let out = generate(code);
        assert!(out.contains("MyType"), "타입명 없음: {}", out);
    }

    // ─── 2. ast_to_ir() — main 블록 ──────────────────────────────────────────

    #[test]
    fn test_ir_let_becomes_assign() {
        let ir = ir!("let x = 42;");
        assert!(!ir.main.is_empty(), "main IR 비어있음");
        let first = &ir.main[0];
        assert!(matches!(first, IRNode::Assign { .. }),
            "Assign 아님: {:?}", first);
    }

    #[test]
    fn test_ir_let_int_literal_value() {
        let ir = ir!("let x = 42;");
        if let IRNode::Assign { value, .. } = &ir.main[0] {
            assert!(matches!(value.as_ref(), IRNode::IntLiteral(42)),
                "IntLiteral(42) 아님: {:?}", value);
        } else {
            panic!("Assign 아님");
        }
    }

    #[test]
    fn test_ir_let_float_literal_value() {
        let ir = ir!("let f = 3.14;");
        if let IRNode::Assign { value, .. } = &ir.main[0] {
            assert!(matches!(value.as_ref(), IRNode::FloatLiteral(_)),
                "FloatLiteral 아님: {:?}", value);
        } else {
            panic!("Assign 아님");
        }
    }

    #[test]
    fn test_ir_let_string_literal_value() {
        let ir = ir!("let s = \"hi\";");
        if let IRNode::Assign { value, .. } = &ir.main[0] {
            assert!(matches!(value.as_ref(), IRNode::StringLiteral(_)),
                "StringLiteral 아님: {:?}", value);
        } else {
            panic!("Assign 아님");
        }
    }

    #[test]
    fn test_ir_let_bool_literal_value() {
        let ir = ir!("let b = true;");
        if let IRNode::Assign { value, .. } = &ir.main[0] {
            assert!(matches!(value.as_ref(), IRNode::BoolLiteral(true)),
                "BoolLiteral(true) 아님: {:?}", value);
        } else {
            panic!("Assign 아님");
        }
    }

    // ─── 3. BinaryOp IR ───────────────────────────────────────────────────────

    #[test]
    fn test_ir_add_expression() {
        let ir = ir!("let r = 1 + 2;");
        if let IRNode::Assign { value, .. } = &ir.main[0] {
            // 상수 폴딩 되거나 BinaryOp 둘 다 허용
            let is_int = matches!(value.as_ref(), IRNode::IntLiteral(_));
            let is_binop = matches!(value.as_ref(), IRNode::BinaryOp { .. });
            assert!(is_int || is_binop, "예상 외 노드: {:?}", value);
        }
    }

    #[test]
    fn test_ir_constant_folding_add() {
        let ir = ir!("let r = 3 + 4;");
        if let IRNode::Assign { value, .. } = &ir.main[0] {
            // 상수 폴딩: 7 이거나 BinaryOp(3,4)
            match value.as_ref() {
                IRNode::IntLiteral(v) => assert_eq!(*v, 7, "폴딩 결과 오류"),
                IRNode::BinaryOp { .. } => {} // 폴딩 미구현도 허용
                other => panic!("예상 외 노드: {:?}", other),
            }
        }
    }

    #[test]
    fn test_ir_binary_op_op_field() {
        // 변수를 사용하면 상수 폴딩 안 됨
        let code = "let a = 1;\nlet b = 2;\nlet c = a + b;";
        let ir = ir!(code);
        assert_eq!(ir.main.len(), 3, "3개 assign 예상");
        if let IRNode::Assign { value, .. } = &ir.main[2] {
            match value.as_ref() {
                IRNode::BinaryOp { op, .. } => {
                    assert!(op.contains("Plus") || op.contains("+"),
                        "op 필드 오류: {}", op);
                }
                IRNode::IntLiteral(_) => {} // 상수 폴딩 허용
                other => panic!("예상 외: {:?}", other),
            }
        }
    }

    // ─── 4. 함수 IR ────────────────────────────────────────────────────────────

    #[test]
    fn test_ir_function_registered() {
        let code = "fn double(n) -> Int { return n; }";
        let ir = ir!(code);
        assert!(!ir.functions.is_empty(), "functions 비어있음");
        assert_eq!(ir.functions[0].name, "double");
    }

    #[test]
    fn test_ir_function_params_count() {
        let code = "fn add(a, b) -> Int { return a; }";
        let ir = ir!(code);
        assert_eq!(ir.functions[0].params.len(), 2,
            "파라미터 수 오류: {:?}", ir.functions[0].params);
    }

    #[test]
    fn test_ir_function_body_not_empty() {
        let code = "fn f() -> Int { return 1; }";
        let ir = ir!(code);
        assert!(!ir.functions[0].body.is_empty(), "함수 body 비어있음");
    }

    #[test]
    fn test_ir_multiple_functions() {
        let code = "fn a() -> Int { return 1; }\nfn b() -> Int { return 2; }";
        let ir = ir!(code);
        assert_eq!(ir.functions.len(), 2, "함수 2개 예상");
    }

    // ─── 5. Return IR ─────────────────────────────────────────────────────────

    #[test]
    fn test_ir_return_node() {
        let code = "fn f() -> Int { return 42; }";
        let ir = ir!(code);
        let body = &ir.functions[0].body;
        assert!(body.iter().any(|n| matches!(n, IRNode::Return(_))),
            "Return 노드 없음: {:?}", body);
    }

    #[test]
    fn test_ir_return_int_value() {
        let code = "fn f() -> Int { return 99; }";
        let ir = ir!(code);
        let body = &ir.functions[0].body;
        let ret = body.iter().find(|n| matches!(n, IRNode::Return(_)));
        if let Some(IRNode::Return(inner)) = ret {
            assert!(matches!(inner.as_ref(), IRNode::IntLiteral(99)),
                "Return 내부 값 오류: {:?}", inner);
        }
    }

    // ─── 6. If IR ──────────────────────────────────────────────────────────────

    #[test]
    fn test_ir_if_node_in_main() {
        let code = "let x = 1;\nif x > 0 {\n  let y = 1;\n}";
        let ir = ir!(code);
        // If 노드가 main 에 있거나 assign 안에 있음
        let has_if = ir.main.iter().any(|n| matches!(n, IRNode::If { .. }));
        let has_assign_with_if = ir.main.iter().any(|n| {
            if let IRNode::Assign { value, .. } = n {
                matches!(value.as_ref(), IRNode::If { .. })
            } else {
                false
            }
        });
        assert!(has_if || has_assign_with_if || !ir.main.is_empty(),
            "If IR 없음: {:?}", ir.main);
    }

    // ─── 7. eval 엔드투엔드 ────────────────────────────────────────────────────

    #[test]
    fn test_eval_arithmetic_expression() {
        let result = crate::get_eval_result("let r = 2 + 3;");
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

    #[test]
    fn test_eval_function_definition() {
        let code = "fn square(n) -> Int {\n  let r = n;\n  return r;\n}";
        let result = crate::get_eval_result(code);
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

    #[test]
    fn test_eval_let_chain() {
        let code = "let a = 1;\nlet b = 2;\nlet c = a + b;";
        let result = crate::get_eval_result(code);
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

    #[test]
    fn test_eval_empty_program() {
        let result = crate::get_eval_result("");
        // 빈 프로그램: success or 파싱 오류 모두 허용
        assert!(result.contains("success"), "JSON 아님: {}", result);
    }
}

