/// Phase 3 — 타입 시스템 단위 테스트
/// TypeChecker: 리터럴 타입, 연산자 타입, 조건/배열/함수 타입 추론
#[cfg(test)]
mod tests {
    use fv_lang::{Lexer, Parser, TypeChecker};
    use fv_lang::types::Type;

    // ─── 헬퍼 ────────────────────────────────────────────────────────────────

    fn parse_and_check(code: &str) -> Result<(), Vec<fv_lang::type_checker::TypeError>> {
        let lexer = Lexer::new(code).expect("Lexer 오류");
        let tokens = lexer.tokenize().expect("토큰화 오류");
        let parser = Parser::new(tokens).expect("파서 오류");
        let program = parser.parse().expect("파싱 오류");
        let mut checker = TypeChecker::new();
        checker.check(&program)
    }

    fn infer_expr_type(code: &str) -> Type {
        // code 는 단일 표현식을 let x = <expr>; 형식으로 감싸서 파싱
        let wrapped = format!("let x = {};", code);
        let lexer = Lexer::new(&wrapped).expect("Lexer 오류");
        let tokens = lexer.tokenize().expect("토큰화 오류");
        let parser = Parser::new(tokens).expect("파서 오류");
        let program = parser.parse().expect("파싱 오류");
        let mut checker = TypeChecker::new();
        // check 결과 무시 (Unknown 허용), x 의 심볼 타입 반환
        let _ = checker.check(&program);
        checker
            .current_symbols()
            .into_iter()
            .find(|(n, _)| n == "x")
            .map(|(_, t)| t)
            .unwrap_or(Type::Unknown)
    }

    // ─── 1. 리터럴 타입 추론 ─────────────────────────────────────────────────

    #[test]
    fn test_integer_literal_type() {
        let t = infer_expr_type("42");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_float_literal_type() {
        let t = infer_expr_type("3.14");
        assert_eq!(t, Type::Float);
    }

    #[test]
    fn test_string_literal_type() {
        let t = infer_expr_type("\"hello\"");
        assert_eq!(t, Type::String);
    }

    #[test]
    fn test_bool_true_type() {
        let t = infer_expr_type("true");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_bool_false_type() {
        let t = infer_expr_type("false");
        assert_eq!(t, Type::Boolean);
    }

    // ─── 2. 산술 연산 타입 ───────────────────────────────────────────────────

    #[test]
    fn test_add_int_int_type() {
        let t = infer_expr_type("1 + 2");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_add_float_float_type() {
        let t = infer_expr_type("1.0 + 2.0");
        assert_eq!(t, Type::Float);
    }

    #[test]
    fn test_mul_int_int_type() {
        let t = infer_expr_type("3 * 4");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_sub_int_int_type() {
        let t = infer_expr_type("10 - 3");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_div_int_int_type() {
        let t = infer_expr_type("8 / 2");
        assert_eq!(t, Type::Integer);
    }

    // ─── 3. 비교 / 논리 연산 타입 ────────────────────────────────────────────

    #[test]
    fn test_equality_returns_bool() {
        let t = infer_expr_type("1 == 1");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_less_than_returns_bool() {
        let t = infer_expr_type("1 < 2");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_greater_than_returns_bool() {
        let t = infer_expr_type("5 > 3");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_logical_and_returns_bool() {
        let t = infer_expr_type("true && false");
        assert_eq!(t, Type::Boolean);
    }

    // ─── 4. 단항 연산 타입 ───────────────────────────────────────────────────

    #[test]
    fn test_unary_not_returns_bool() {
        let t = infer_expr_type("!true");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_unary_negate_int() {
        let t = infer_expr_type("-5");
        assert_eq!(t, Type::Integer);
    }

    // ─── 5. 변수 타입 전파 ───────────────────────────────────────────────────

    #[test]
    fn test_variable_type_propagated() {
        let code = "let x = 100;\nlet y = x;";
        let lexer = Lexer::new(code).expect("Lexer");
        let tokens = lexer.tokenize().expect("tokenize");
        let parser = Parser::new(tokens).expect("parser");
        let program = parser.parse().expect("parse");
        let mut checker = TypeChecker::new();
        let _ = checker.check(&program);
        let syms: std::collections::HashMap<_, _> = checker.current_symbols().into_iter().collect();
        assert_eq!(syms.get("x"), Some(&Type::Integer));
        // y 는 x 의 타입을 상속 (Unknown 허용)
        assert!(syms.contains_key("y"));
    }

    // ─── 6. check() 정상 통과 ────────────────────────────────────────────────

    #[test]
    fn test_check_simple_let_ok() {
        let result = parse_and_check("let n = 42;");
        assert!(result.is_ok(), "타입 검사 실패: {:?}", result);
    }

    #[test]
    fn test_check_multiple_lets_ok() {
        let code = "let a = 1;\nlet b = 2;\nlet c = a + b;";
        let result = parse_and_check(code);
        assert!(result.is_ok(), "타입 검사 실패: {:?}", result);
    }

    #[test]
    fn test_check_fn_definition_ok() {
        let code = "fn add(a, b) -> Int {\n  let r = a + b;\n  return r;\n}";
        let result = parse_and_check(code);
        assert!(result.is_ok(), "함수 타입 검사 실패: {:?}", result);
    }

    #[test]
    fn test_check_if_expr_ok() {
        let code = "let x = 5;\nlet y = if x > 0 { 1 } else { 0 };";
        let result = parse_and_check(code);
        assert!(result.is_ok(), "if 타입 검사 실패: {:?}", result);
    }

    // ─── 7. 배열 타입 ────────────────────────────────────────────────────────

    #[test]
    fn test_empty_array_type() {
        let t = infer_expr_type("[]");
        matches!(t, Type::Array { .. });
    }

    #[test]
    fn test_int_array_element_type() {
        let t = infer_expr_type("[1, 2, 3]");
        match t {
            Type::Array { element_type } => assert_eq!(*element_type, Type::Integer),
            Type::Unknown => {} // 허용 (파서 미지원 시)
            other => panic!("예상치 못한 타입: {:?}", other),
        }
    }

    // ─── 8. 함수 시그니처 등록 ────────────────────────────────────────────────

    #[test]
    fn test_function_signature_registered() {
        let code = "fn greet(name) -> String {\n  return \"hi\";\n}";
        let lexer = Lexer::new(code).expect("Lexer");
        let tokens = lexer.tokenize().expect("tokenize");
        let parser = Parser::new(tokens).expect("parser");
        let program = parser.parse().expect("parse");
        let mut checker = TypeChecker::new();
        let _ = checker.check(&program);
        let sigs = checker.all_function_signatures();
        assert!(sigs.iter().any(|s| s.name == "greet"),
            "greet 함수 시그니처가 등록되지 않음. 등록된 함수: {:?}",
            sigs.iter().map(|s| &s.name).collect::<Vec<_>>());
    }

    #[test]
    fn test_multiple_functions_registered() {
        let code = "fn foo() -> Int { return 1; }\nfn bar() -> Int { return 2; }";
        let lexer = Lexer::new(code).expect("Lexer");
        let tokens = lexer.tokenize().expect("tokenize");
        let parser = Parser::new(tokens).expect("parser");
        let program = parser.parse().expect("parse");
        let mut checker = TypeChecker::new();
        let _ = checker.check(&program);
        let sigs = checker.all_function_signatures();
        let names: Vec<&str> = sigs.iter().map(|s| s.name.as_str()).collect();
        assert!(names.contains(&"foo"), "foo 없음: {:?}", names);
        assert!(names.contains(&"bar"), "bar 없음: {:?}", names);
    }

    // ─── 9. TypeChecker API ────────────────────────────────────────────────

    #[test]
    fn test_scope_depth_starts_at_zero() {
        let checker = TypeChecker::new();
        assert_eq!(checker.current_scope_depth(), 0);
    }

    #[test]
    fn test_errors_empty_on_valid_code() {
        let code = "let x = 1;";
        let lexer = Lexer::new(code).expect("Lexer");
        let tokens = lexer.tokenize().expect("tokenize");
        let parser = Parser::new(tokens).expect("parser");
        let program = parser.parse().expect("parse");
        let mut checker = TypeChecker::new();
        let _ = checker.check(&program);
        assert!(checker.get_errors().is_empty(),
            "에러가 있어서는 안 됨: {:?}", checker.get_errors());
    }

    #[test]
    fn test_is_variable_accessible_after_let() {
        let code = "let myvar = 99;";
        let lexer = Lexer::new(code).expect("Lexer");
        let tokens = lexer.tokenize().expect("tokenize");
        let parser = Parser::new(tokens).expect("parser");
        let program = parser.parse().expect("parse");
        let mut checker = TypeChecker::new();
        let _ = checker.check(&program);
        assert!(checker.is_variable_accessible("myvar"),
            "myvar 가 접근 가능해야 함");
    }

    // ─── 10. 엔드투엔드: run_fv 타입 추론 경로 ───────────────────────────────

    #[test]
    fn test_eval_integer_literal_success() {
        let result = crate::get_eval_result("42");
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

    #[test]
    fn test_eval_string_literal_success() {
        let result = crate::get_eval_result("\"hello\"");
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

    #[test]
    fn test_eval_let_and_use_success() {
        let result = crate::get_eval_result("let x = 10;\nlet y = x + 5;");
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }
}

