        let parser = Parser::new(tokens).expect("파서 오류");
        let program = parser.parse().expect("파싱 오류");
        let mut checker = TypeChecker::new();
        checker.check(&program)
    }

    fn infer_expr_type(code: &str) -> Type {
        // code 는 단일 표현식 — check_expression 으로 직접 타입 추론
        let wrapped = format!("let x = {};", code);
        let lexer = Lexer::new(&wrapped).expect("Lexer 오류");
        let tokens = lexer.tokenize().expect("토큰화 오류");
        let parser = Parser::new(tokens).expect("파서 오류");
        let program = parser.parse().expect("파싱 오류");
        // statements[0] 은 LetBinding { name, value }
        if let Some(fv_lang::ast::Statement::LetBinding { value, .. }) = program.statements.first() {
            let mut checker = TypeChecker::new();
            checker.check_expression(value).unwrap_or(Type::Unknown)
        } else {
            Type::Unknown
        }
    }

    // ─── 1. 리터럴 타입 추론 ─────────────────────────────────────────────────

    #[test]
    fn test_integer_literal_type() {
        let t = infer_expr_type("42");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_float_literal_type() {
        let t = infer_expr_type("3.14");
        assert_eq!(t, Type::Float);
    }

    #[test]
    fn test_string_literal_type() {
        let t = infer_expr_type("\"hello\"");
        assert_eq!(t, Type::String);
    }

    #[test]
    fn test_bool_true_type() {
        let t = infer_expr_type("true");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_bool_false_type() {
        let t = infer_expr_type("false");
        assert_eq!(t, Type::Boolean);
    }

    // ─── 2. 산술 연산 타입 ───────────────────────────────────────────────────

    #[test]
    fn test_add_int_int_type() {
        let t = infer_expr_type("1 + 2");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_add_float_float_type() {
        let t = infer_expr_type("1.0 + 2.0");
        assert_eq!(t, Type::Float);
    }

    #[test]
    fn test_mul_int_int_type() {
        let t = infer_expr_type("3 * 4");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_sub_int_int_type() {
        let t = infer_expr_type("10 - 3");
        assert_eq!(t, Type::Integer);
    }

    #[test]
    fn test_div_int_int_type() {
        let t = infer_expr_type("8 / 2");
        assert_eq!(t, Type::Integer);
    }

