    #[test]
    fn test_eval_integer_literal_success() {
        let result = crate::get_eval_result("42");
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

    #[test]
    fn test_eval_string_literal_success() {
        let result = crate::get_eval_result("\"hello\"");
        assert!(result.contains("\"success\":true"), "결과: {}", result);
    }

