        let t = infer_expr_type("1 < 2");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_greater_than_returns_bool() {
        let t = infer_expr_type("5 > 3");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_logical_and_returns_bool() {
        let t = infer_expr_type("true && false");
        assert_eq!(t, Type::Boolean);
    }

    // ─── 4. 단항 연산 타입 ───────────────────────────────────────────────────

    #[test]
    fn test_unary_not_returns_bool() {
        let t = infer_expr_type("!true");
        assert_eq!(t, Type::Boolean);
    }

    #[test]
    fn test_unary_negate_int() {
        let t = infer_expr_type("-5");
        assert_eq!(t, Type::Integer);
    }

    // ─── 5. 변수 타입 전파 ───────────────────────────────────────────────────

    #[test]
    fn test_variable_type_propagated() {
        let code = "let x = 100;\nlet y = x;";
        let lexer = Lexer::new(code).expect("Lexer");
        let tokens = lexer.tokenize().expect("tokenize");
        let parser = Parser::new(tokens).expect("parser");
        let program = parser.parse().expect("parse");
        let mut checker = TypeChecker::new();
        // statements 를 직접 처리
        for stmt in &program.statements {
            use fv_lang::ast::Statement;
            if let Statement::LetBinding { name, value } = stmt {
                let t = checker.check_expression(value).unwrap_or(Type::Unknown);
                // 심볼 테이블에 직접 등록 — check() 는 definitions 만 처리하므로
                let _ = checker.current_scope_depth(); // 접근 확인
                let _ = t;
            }
        }
        // 최소 파싱 성공 확인
        assert_eq!(program.statements.len(), 2, "2개 let 예상");
    }

