    let program = parser.parse().expect("parse");
    assert!(!program.definitions.is_empty(), "함수 정의 파싱 실패");
    let mut checker = TypeChecker::new();
    let _ = checker.check(&program);
    let sig = checker.get_function_signature("greet");
    assert!(sig.is_some(), "greet 함수 시그니처가 등록되지 않음");
