/**
 * FreeWire - 브라우저 실행 엔진 (Node.js 서버사이드 + 브라우저 공용)
 * .free 코드를 파싱 → HTML/CSS/JS 변환 → 실시간 실행
 * WASM 없이 순수 JS로 동작하지만 WASM Bridge 인터페이스 제공
 */

// ─── FreeLang Light 인라인 파서 ─────────────────────────────────
class FreeLangParser {
  constructor() { this.reset(); }

  reset() {
    this.props   = {};
    this.style   = '';
    this.script  = '';
    this.markup  = '';
    this.name    = 'Component';
  }

  parse(code) {
    this.reset();
    if (typeof code !== 'string') return this;

    // 컴포넌트 이름 추출
    const nameMatch = code.match(/component\s+(\w+)/);
    if (nameMatch) this.name = nameMatch[1];

    // 섹션 추출 (중첩 {} 지원)
    this.props  = this._extractProps(code);
    this.style  = this._extractBlock(code, 'style');
    this.script = this._extractBlock(code, 'script');

