/**
 * FreeWire Phase 11 — WASM 브리지 + BrowserExecutor 테스트
 * browser-executor.js 의 전체 파이프라인 검증
 */

const path = require('path');

// Node.js 환경에서 browser-executor 로드
const executorPath = path.join(__dirname, '../wasm/browser-executor.js');
let BrowserExecutor;
try {
  const mod = require(executorPath);
  BrowserExecutor = mod.BrowserExecutor || mod;
} catch (e) {
  console.error('browser-executor.js 로드 실패:', e.message);
  process.exit(1);
}

// ─── 테스트 러너 ───────────────────────────────────────────────
let passed = 0;
let failed = 0;
const errors = [];

function test(name, fn) {
  try {
    fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    errors.push({ name, error: e.message });
    failed++;
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg || '조건 실패');
}
function assertEqual(a, b, msg) {
  if (a !== b) throw new Error(msg || `${JSON.stringify(a)} !== ${JSON.stringify(b)}`);
}
function assertIncludes(str, substr, msg) {
  if (!str.includes(substr)) throw new Error(msg || `"${substr}" not in "${str.slice(0,120)}"`);
}

// ─── 1. BrowserExecutor 초기화 ───────────────────────────────
console.log('\n📦 Phase 11: BrowserExecutor + WASM 브리지\n');
console.log('1. BrowserExecutor 초기화');

test('BrowserExecutor 클래스 로드 성공', () => {
  assert(typeof BrowserExecutor === 'function', 'BrowserExecutor 클래스여야 함');
});

test('인스턴스 생성 성공', () => {
  const ex = new BrowserExecutor();
  assert(ex !== null && typeof ex === 'object');
});

test('execute() 메서드 존재', () => {
  const ex = new BrowserExecutor();
  assert(typeof ex.execute === 'function');
});

test('buildPreviewHTML() 메서드 존재', () => {
  const ex = new BrowserExecutor();
  assert(typeof ex.buildPreviewHTML === 'function');
});

// ─── 2. execute() 기본 동작 ──────────────────────────────────
console.log('\n2. execute() 기본 동작');

test('빈 코드 → 빈 결과 반환', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute('');
  assert(r !== null && typeof r === 'object');
  assertEqual(r.html, '', '빈 html 예상');
  assertEqual(r.css,  '', '빈 css 예상');
  assertEqual(r.js,   '', '빈 js 예상');
});

test('null 입력 → 빈 결과 반환', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(null);
  assert(typeof r === 'object' && r !== null);
});

test('비문자열 입력 → 빈 결과 반환', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(42);
  assert(typeof r === 'object');
});

test('stats 객체 포함', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute('component Test { markup { <p>hi</p> } }');
  assert(r.stats !== null && typeof r.stats === 'object');
  assert('htmlBytes' in r.stats, 'htmlBytes 없음');
  assert('cssBytes' in r.stats, 'cssBytes 없음');
  assert('jsBytes' in r.stats, 'jsBytes 없음');
});

// ─── 3. 컴포넌트 파싱 ────────────────────────────────────────
console.log('\n3. 컴포넌트 파싱');

const sampleFree = `component Counter {
  script {
    let count = 0;
    function increment() { count = count + 1; }
  }
  style {
    .counter { padding: 20px; }
  }
  markup {
    <div class="counter">
      <h2>카운트: {{count}}</h2>
      <button onclick="increment()">+1</button>
    </div>
  }
}`;

test('component 이름 파싱', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assertEqual(r.name, 'Counter', `이름 오류: ${r.name}`);
});

test('script → js 생성', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assert(r.js.length > 0, 'js 비어있음');
});

test('style → css 생성', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assert(r.css.length > 0, 'css 비어있음');
});

test('markup → html 생성', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assert(r.html.length > 0, 'html 비어있음');
});

test('stats.hasStyle true', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assertEqual(r.stats.hasStyle, true);
});

test('stats.hasScript true', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assertEqual(r.stats.hasScript, true);
});

test('htmlBytes = html.length', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assertEqual(r.stats.htmlBytes, r.html.length);
});

// ─── 4. buildPreviewHTML ────────────────────────────────────
console.log('\n4. buildPreviewHTML()');

test('결과 포함 → 완전한 HTML 문서 반환', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  const html = ex.buildPreviewHTML(r);
  assertIncludes(html, '<!DOCTYPE html>', 'DOCTYPE 없음');
  assertIncludes(html, '</html>', '닫는 html 태그 없음');
});

test('null 결과 → 기본 HTML 반환', () => {
  const ex = new BrowserExecutor();
  const html = ex.buildPreviewHTML(null);
  assertIncludes(html, '<!DOCTYPE html>');
});

test('CSS 내용 포함', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  const html = ex.buildPreviewHTML(r);
  assertIncludes(html, '<style>', 'style 태그 없음');
});

test('JS 내용 포함', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  const html = ex.buildPreviewHTML(r);
  assertIncludes(html, '<script>', 'script 태그 없음');
});

// ─── 5. history 관리 ─────────────────────────────────────────
console.log('\n5. history 관리');

test('실행 후 history에 기록', () => {
  const ex = new BrowserExecutor();
  ex.execute(sampleFree);
  assert(ex.history.length > 0, 'history 비어있음');
});

test('history 항목에 code 포함', () => {
  const ex = new BrowserExecutor();
  ex.execute(sampleFree);
  assert(ex.history[0].code === sampleFree);
});

test('history 항목에 result 포함', () => {
  const ex = new BrowserExecutor();
  ex.execute(sampleFree);
  assert(typeof ex.history[0].result === 'object');
});

test('history 항목에 ts 포함', () => {
  const ex = new BrowserExecutor();
  ex.execute(sampleFree);
  assert(typeof ex.history[0].ts === 'number');
});

test('history 최대 50개 제한', () => {
  const ex = new BrowserExecutor();
  for (let i = 0; i < 60; i++) {
    ex.execute(`component C${i} { markup { <p>${i}</p> } }`);
  }
  assert(ex.history.length <= 50, `${ex.history.length} > 50`);
});

// ─── 6. XSS 방어 ─────────────────────────────────────────────
console.log('\n6. XSS / 인젝션 방어');

test('style 블록에 <script> 태그 차단', () => {
  const ex = new BrowserExecutor();
  const malicious = `component X {
    style { <script>alert(1)</script> .x { color: red; } }
    markup { <p>test</p> }
  }`;
  const r = ex.execute(malicious);
  // CSS 결과에 <script> 가 그대로 있어선 안 됨
  assert(!r.css.includes('<script>alert'), `CSS XSS 미차단: ${r.css.slice(0,100)}`);
});

test('markup {{변수}} 치환 동작', () => {
  const ex = new BrowserExecutor();
  const code = `component A {
    script { let msg = "hello"; }
    markup { <p>{{msg}}</p> }
  }`;
  const r = ex.execute(code);
  // {{msg}} 가 data-bind 속성 또는 치환됨
  assert(r.html.length > 0);
});

// ─── 7. WASM 브리지 인터페이스 ───────────────────────────────
console.log('\n7. WASM 브리지 인터페이스');

test('module.exports 에 BrowserExecutor 노출', () => {
  const mod = require(executorPath);
  assert(
    typeof mod === 'function' || typeof mod.BrowserExecutor === 'function',
    'exports 오류'
  );
});

test('여러 인스턴스가 독립적으로 동작', () => {
  const ex1 = new BrowserExecutor();
  const ex2 = new BrowserExecutor();
  ex1.execute(sampleFree);
  assertEqual(ex2.history.length, 0, 'history 공유됨');
});

test('parseMs가 숫자형', () => {
  const ex = new BrowserExecutor();
  const r = ex.execute(sampleFree);
  assertEqual(typeof r.stats.parseMs, 'number');
});

// ─── 결과 ─────────────────────────────────────────────────────
console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
if (errors.length > 0) {
  console.log('\n실패 목록:');
  errors.forEach(e => console.log(`  ❌ ${e.name}: ${e.error}`));
}
process.exit(failed > 0 ? 1 : 0);

