 * FreeWire - 브라우저 실행 엔진 (Node.js 서버사이드 + 브라우저 공용)
 * .free 코드를 파싱 → HTML/CSS/JS 변환 → 실시간 실행
 * WASM 없이 순수 JS로 동작하지만 WASM Bridge 인터페이스 제공
 */

// ─── FreeLang Light 인라인 파서 ─────────────────────────────────
class FreeLangParser {
  constructor() { this.reset(); }

  reset() {
    this.props   = {};
    this.style   = '';
    this.script  = '';
    this.markup  = '';
    this.name    = 'Component';
  }

  parse(code) {
    this.reset();
    if (typeof code !== 'string') return this;

    // 컴포넌트 이름 추출
    const nameMatch = code.match(/component\s+(\w+)/);
    if (nameMatch) this.name = nameMatch[1];

    // 섹션 추출 (중첩 {} 지원)
    this.props  = this._extractProps(code);
    this.style  = this._extractBlock(code, 'style');
    this.script = this._extractBlock(code, 'script');
    this.markup = this._extractBlock(code, 'markup');

    return this;
  }

  _extractBlock(code, keyword) {
    const re = new RegExp(`\\b${keyword}\\s*\\{`);
    const m  = re.exec(code);
    if (!m) return '';
    let depth = 1, i = m.index + m[0].length;
    const start = i;
    while (i < code.length && depth > 0) {
      if (code[i] === '{') depth++;
      else if (code[i] === '}') depth--;
      i++;
    }
    return code.slice(start, i - 1).trim();
  }

  _extractProps(code) {
    const block = this._extractBlock(code, 'props');
    const props = {};
    if (!block) return props;
    const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
    lines.forEach(line => {
      const m = line.match(/^(\w+)\s*:\s*\w+\s*(?:=\s*(.+?))?;?\s*$/);
      if (m) props[m[1]] = (m[2] || '').replace(/['"]/g, '').replace(/;$/, '').trim();
    });
    return props;
  }
}

// ─── CSS 컴파일러 ────────────────────────────────────────────────
class CSSCompiler {
  compile(styleBlock) {
    if (!styleBlock || !styleBlock.trim()) return '';
    return styleBlock
      .replace(/([a-z])([A-Z])/g, '$1-$2')
      .toLowerCase()
      .trim();
  }
}

// ─── JS 컴파일러 ─────────────────────────────────────────────────
class JSCompiler {
  compile(scriptBlock, componentName) {
    if (!scriptBlock || !scriptBlock.trim()) return '';

    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    const out   = [];

    out.push(`/* FreeWire: ${componentName} */`); // eslint-disable-line
    out.push('(function(fw) {');
    out.push('  "use strict";');

    // 상태 변수 추적
    const stateVars = [];
    lines.forEach(line => {
      // state setter 감지: function set_xxx(v) { xxx = v; }
      const setterMatch = line.match(/^function\s+set_(\w+)\(/);
      if (setterMatch) stateVars.push(setterMatch[1]);

      out.push('  ' + line);
    });

    // state 변경 시 DOM 업데이트
    out.push('');
    out.push('  // 반응형 DOM 업데이트');
    out.push('  function __fw_update() {');
    out.push('    var els = document.querySelectorAll("[data-fw-bind]");');
    out.push('    els.forEach(function(el) {');
    out.push('      var key = el.getAttribute("data-fw-bind");');
    out.push('      try { el.textContent = eval(key); } catch(e) {}');
    out.push('    });');
    // state setter 오버라이드 (업데이트 자동 트리거)
    stateVars.forEach(v => {
      out.push(`    if (typeof ${v} !== "undefined" && fw.__prev_${v} !== ${v}) {`);
      out.push(`      fw.__prev_${v} = ${v};`);
      out.push('    }');
    });
    out.push('  }');
    out.push('');

    // setter 오버라이드 (원본 setter 호출 후 __fw_update)
    stateVars.forEach(v => {
      out.push(`  var __orig_set_${v} = typeof set_${v} === "function" ? set_${v} : null;`);
      out.push(`  set_${v} = function(v) { if (__orig_set_${v}) __orig_set_${v}(v); __fw_update(); };`);
    });

    // 이벤트 바인딩
    out.push('');
    out.push('  document.addEventListener("DOMContentLoaded", function() {');
    out.push('    __fw_update();');
    out.push('    // 버튼 이벤트 자동 바인딩');
    out.push('    document.querySelectorAll("[data-fw-action]").forEach(function(el) {');
    out.push('      var action = el.getAttribute("data-fw-action");');
    out.push('      el.addEventListener("click", function() {');
    out.push('        try { eval(action + "()"); __fw_update(); } catch(e) { console.warn("FW:", e); }');
    out.push('      });');
    out.push('    });');
    out.push('  });');
    out.push('})({});');

    return out.join('\n');
  }
}

// ─── HTML 컴파일러 ───────────────────────────────────────────────
class HTMLCompiler {
  compile(markupBlock) {
    if (!markupBlock || !markupBlock.trim()) return '';

    return markupBlock
      .replace(/\bmarkup\s*\{/g, '')
      .replace(/^\s*\}\s*$/gm, '')
      // {{변수}} → data-fw-bind 속성
      .replace(/\{\{(\w+)\}\}/g, '<span data-fw-bind="$1">$1</span>')
      // 버튼 클릭 함수 자동 감지: onclick="xxx()" → data-fw-action
      .replace(/onclick="(\w+)\(\)"/g, 'data-fw-action="$1"')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }
}

// ─── 메인 실행 엔진 ──────────────────────────────────────────────
class BrowserExecutor {
  constructor() {
    this.parser  = new FreeLangParser();
    this.css     = new CSSCompiler();
    this.js      = new JSCompiler();
    this.html    = new HTMLCompiler();
    this.history = [];
  }

  /**
   * .free 코드 → { html, css, js, name, stats }
   */
  execute(freeCode) {
    if (typeof freeCode !== 'string' || !freeCode.trim()) {
      return { name: 'Component', html: '', css: '', js: '', props: {}, stats: { parseMs: 0, htmlBytes: 0, cssBytes: 0, jsBytes: 0, hasStyle: false, hasScript: false } };
    }
    const start = Date.now();
    const parsed = this.parser.parse(freeCode);

    const css  = this.css.compile(parsed.style);
    const js   = this.js.compile(parsed.script, parsed.name);
    const html = this.html.compile(parsed.markup);

    const result = {
      name:  parsed.name,
      html,  css, js,
      props: parsed.props,
      stats: {
        parseMs:   Date.now() - start,
        htmlBytes: html.length,
        cssBytes:  css.length,
        jsBytes:   js.length,
        hasStyle:  css.length > 0,
        hasScript: js.length > 0,
      },
    };

    this.history.push({ code: freeCode, result, ts: Date.now() });
    if (this.history.length > 50) this.history.shift();

    return result;
  }

  /**
   * 전체 미리보기 HTML 생성 (iframe srcdoc용)
   */
  buildPreviewHTML(result) {
    if (!result || typeof result !== 'object') {
      result = { html: '', css: '', js: '' };
    }
    // CSS 인젝션 방어: </style> 태그 이스케이프
    const safeCss = (result.css || '').replace(/<\/style>/gi, '<\\/style>');
    const safeJs  = (result.js  || '');
    const safeHtml = (result.html || '<p style="color:#9ca3af">내용 없음</p>');
    return `<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: system-ui, sans-serif; padding: 20px; background: #f8fafc; }
  button { cursor: pointer; padding: 8px 16px; border: none; border-radius: 6px; font-size: 14px; }
  button.primary   { background: #6366f1; color: #fff; }
  button.secondary { background: #e2e8f0; color: #374151; }
  button.ghost     { background: transparent; border: 1px solid #d1d5db; color: #374151; }
  input { padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; width: 100%; }
  .card { background: #fff; border-radius: 12px; padding: 20px; box-shadow: 0 2px 8px rgba(0,0,0,.08); }
  .card.glass { background: rgba(255,255,255,.2); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.3); }
  .container { display: flex; }
  .container.column { flex-direction: column; }
  .container.row    { flex-direction: row; }
  .freewire-badge {
    position: fixed; bottom: 8px; right: 8px;
    background: #6366f1; color: #fff;
    padding: 3px 8px; border-radius: 999px; font-size: 11px; opacity: .8;
  }
  ${safeCss}
</style>
</head>
<body>
<div id="fw-root">${safeHtml}</div>
<div class="freewire-badge">⚡ FreeWire</div>
<script>${safeJs}</script>
</body>
</html>`;
  }

  /** 마지막 실행 결과 */
  lastResult() { return this.history[this.history.length - 1]?.result || null; }

  /** 히스토리 초기화 */
  clearHistory() { this.history = []; }
}

// ─── WASM Bridge 인터페이스 (미래 확장용) ───────────────────────
const WASMBridge = {
  _executor: new BrowserExecutor(),
  _ready: true,

  /** WASM 준비 여부 */
  isReady() { return this._ready; },

  /** .free 코드 컴파일 */
  compile(freeCode) {
    if (!this._ready) throw new Error('WASMBridge not ready');
    return this._executor.execute(freeCode);
  },

  /** 미리보기 HTML 생성 */
  preview(freeCode) {
    if (!this._ready) throw new Error('WASMBridge not ready');
    const result = this.compile(freeCode);
    return this._executor.buildPreviewHTML(result);
  },

  /** 히스토리 */
  history() { return this._executor.history; },
};

// Node.js / 브라우저 공용 export
if (typeof module !== 'undefined') {
  module.exports = { BrowserExecutor, WASMBridge, FreeLangParser, CSSCompiler, JSCompiler, HTMLCompiler };
} else {
  window.FreeWireWASM = WASMBridge;
  window.BrowserExecutor = BrowserExecutor;
}

