/**
 * FreeWire - 노드 그래프 (노드 + 엣지 컨테이너)
 */

const { validateNode, validateEdge } = require('./node-spec');

class Graph {
  constructor(id = 'graph-001') {
    this.id    = id;
    this.nodes = [];   // { id, type, ... }
    this.edges = [];   // { id, from: {nodeId, portId, portType}, to: {nodeId, portId, portType} }
  }

  // ─── 노드 ─────────────────────────────────────────────────────
  addNode(node) {
    const { valid, errors } = validateNode(node);
    if (!valid) throw new Error(`노드 오류 [${node.id}]: ${errors.join(', ')}`);
    if (this.nodes.find(n => n.id === node.id))
      throw new Error(`중복 노드 id: ${node.id}`);
    this.nodes.push(node);
    return this;
  }

  removeNode(nodeId) {
    this.nodes  = this.nodes.filter(n => n.id !== nodeId);
    this.edges  = this.edges.filter(e => e.from.nodeId !== nodeId && e.to.nodeId !== nodeId);
    return this;
  }

  getNode(nodeId) {
    return this.nodes.find(n => n.id === nodeId) || null;
  }

  // ─── 엣지 ─────────────────────────────────────────────────────
  addEdge(edge) {
    const { valid, errors } = validateEdge(edge, this.nodes);
    if (!valid) throw new Error(`엣지 오류 [${edge.id}]: ${errors.join(', ')}`);
    if (this.edges.find(e => e.id === edge.id))
      throw new Error(`중복 엣지 id: ${edge.id}`);
    this.edges.push(edge);

